Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section Segs.
Context {fx : FPState}.
Variable rom : word -> option byte.
Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

(* [comment removed for export] *)
Lemma rbn_run : forall regs m,
  rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
  getr regs 10 = Z_to_bv 64 0 ->
  exists regs',
    msteps SEGS (mkst regs (0x6f3cc : word) m rom) (mkst regs' (0x6311c : word) m rom)
    /\ getr regs' 10 = Z_to_bv 64 0x10355 /\ getr regs' 11 = Z_to_bv 64 0x1710e /\ getr regs' 12 = Z_to_bv 64 0
    /\ regs_agree (fun r => In r [10; 11; 12]%list) regs regs'.
Proof.
